function validate([arr, pieces]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100) return 'arr needs 1 to 100 values.';
  if (!Array.isArray(pieces) || pieces.length < 1 || pieces.length > arr.length) return 'pieces needs 1 to arr.length arrays.';
  if (pieces.some(piece => !Array.isArray(piece) || piece.length < 1)) return 'Every piece needs at least one value.';
  const flat = pieces.flat();
  if (flat.length !== arr.length) return 'The pieces must hold arr.length values in total.';
  if ([...arr, ...flat].some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Every value is an integer from 1 to 100.';
  if (new Set(arr).size !== arr.length) return 'The values in arr must be distinct.';
  if (new Set(flat).size !== flat.length) return 'The values across pieces must be distinct.';
  return null;
}

