  for (const piece of pieces) {
    pieceByFirst.set(piece[0], piece);
  }

  let i = 0;
  while (i < arr.length) {
    const piece = pieceByFirst.get(arr[i]);
    if (piece === undefined) {
      return false;
    }
    for (const value of piece) {
      if (arr[i] !== value) {
        return false;
      }
      i++;
    }
  }
