function canFormArray(arr, pieces) {
  // Try every order of the pieces and compare the joined result with arr.
  const target = arr.join(',');
  const used = new Array(pieces.length).fill(false);
  const order = [];
  const tryOrders = () => {
    if (order.length === pieces.length) return order.flat().join(',') === target;
    for (let k = 0; k < pieces.length; k++) {
      if (used[k]) continue;
      used[k] = true;
      order.push(pieces[k]);
      const found = tryOrders();
      order.pop();
      used[k] = false;
      if (found) return true;
    }
    return false;
  };
  return tryOrders();
}

