function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const n = size === 'large' ? 100 : 1 + pick(7);
  const pool = shuffle(Array.from({ length: 100 }, (_, i) => i + 1));
  const arr = pool.slice(0, n);
  const spare = pool.slice(n);
  // Cut arr into consecutive chunks.
  const pieces = [];
  let start = 0;
  const longest = size === 'large' ? 1 + pick(12) : 1 + pick(3);
  while (start < n) {
    const len = Math.min(n - start, 1 + pick(longest));
    pieces.push(arr.slice(start, start + len));
    start += len;
  }
  const mode = rand();
  if (mode < 0.15) {
    // Swap one value for a number that is not in arr.
    const piece = pieces[pick(pieces.length)];
    piece[pick(piece.length)] = spare[0];
  } else if (mode < 0.3 && n > 1) {
    // Swap two values across (or inside) pieces.
    const p = pieces[pick(pieces.length)], q = pieces[pick(pieces.length)];
    const x = pick(p.length), y = pick(q.length);
    [p[x], q[y]] = [q[y], p[x]];
  } else if (mode < 0.45) {
    // Reverse one piece.
    pieces[pick(pieces.length)].reverse();
  }
  return [arr, shuffle(pieces)];
}
